+    // Build the block body: cpu_id + [flags] + ts + tid + event_len + event_type + [nparams] + event_data
+    uint32_t body_len = 2 + (has_flags ? 4 : 0) + 8 + 8 + 4 + 2 + (has_nparams ? 4 : 0) + event_data_len;
